const upsertPolicyResult = `-- name: UpsertPolicyResult :exec
INSERT INTO inventory_policy_result (device_id, organization_id, policy_key, passing, updated_at)
VALUES ($1, $2, $3, $4, now())
ON CONFLICT (device_id, policy_key) DO UPDATE
  SET passing = EXCLUDED.passing,
      updated_at = CASE WHEN inventory_policy_result.passing = EXCLUDED.passing THEN inventory_policy_result.updated_at ELSE now() END,
      alerted_at = CASE WHEN EXCLUDED.passing THEN NULL ELSE inventory_policy_result.alerted_at END
`

type UpsertPolicyResultParams struct {
	DeviceID       uuid.UUID
	OrganizationID uuid.UUID
	PolicyKey      string
	Passing        bool
}

// updated_at is when the result last changed; a policy that passes again ends its mutual watch alert.
func (q *Queries) UpsertPolicyResult(ctx context.Context, arg UpsertPolicyResultParams) error {
	_, err := q.db.Exec(ctx, upsertPolicyResult,
		arg.DeviceID,
		arg.OrganizationID,
		arg.PolicyKey,
		arg.Passing,
	)
	return err
}

const upsertVulnerabilityFindings = `-- name: UpsertVulnerabilityFindings :exec
INSERT INTO vulnerability_finding (device_id, organization_id, cve, software_name, software_version, cvss_score, severity, fixed_version,
                                   fleet_severity, fleet_fixed_version)
SELECT $1, $2, k.cve, k.name, k.version, NULLIF(k.cvss, -1)::numeric(3,1), NULLIF(k.severity, ''),
       NULLIF(k.fixed, ''), NULLIF(k.severity, ''), NULLIF(k.fixed, '')
FROM (SELECT unnest($3::text[]) AS cve, unnest($4::text[]) AS name, unnest($5::text[]) AS version,
             unnest($6::float8[]) AS cvss, unnest($7::text[]) AS severity, unnest($8::text[]) AS fixed) k
ON CONFLICT (device_id, cve, software_name, software_version) DO UPDATE
  SET cvss_score = EXCLUDED.cvss_score, severity = EXCLUDED.severity, fixed_version = EXCLUDED.fixed_version,
      fleet_severity = EXCLUDED.fleet_severity, fleet_fixed_version = EXCLUDED.fleet_fixed_version, cvss_vector = NULL
`

type UpsertVulnerabilityFindingsParams struct {
	DeviceID       uuid.UUID
	OrganizationID uuid.UUID
	Cves           []string
	Names          []string
	Versions       []string
	Cvss           []float64
	Severities     []string
	Fixed          []string
}

// The arrays are parallel; cvss -1 and empty strings stand for unknown values. The CVSS vector comes from Ubuntu's
// data only: the enrichment in the same transaction sets it again (plan M5c decision 2).
func (q *Queries) UpsertVulnerabilityFindings(ctx context.Context, arg UpsertVulnerabilityFindingsParams) error {
	_, err := q.db.Exec(ctx, upsertVulnerabilityFindings,
		arg.DeviceID,
		arg.OrganizationID,
		arg.Cves,
		arg.Names,
		arg.Versions,
		arg.Cvss,
		arg.Severities,
		arg.Fixed,
	)
	return err
}

const vulnerabilitySummary = `-- name: VulnerabilitySummary :one
SELECT count(DISTINCT f.device_id) FILTER (WHERE f.severity IN ('critical','high'))::int AS critical_high_devices,
       count(DISTINCT f.device_id) FILTER (WHERE f.severity IS NULL)::int AS unknown_severity_devices,
       count(DISTINCT f.device_id)::int AS affected_devices
FROM vulnerability_finding f JOIN device d ON d.id = f.device_id AND d.state IN ('active','quarantined')
`

type VulnerabilitySummaryRow struct {
	CriticalHighDevices    int32
	UnknownSeverityDevices int32
	AffectedDevices        int32
}

// The dashboard tile (plan M5a decision 10): devices with critical or high findings, and devices with findings of
// unknown severity.
func (q *Queries) VulnerabilitySummary(ctx context.Context) (VulnerabilitySummaryRow, error) {
	row := q.db.QueryRow(ctx, vulnerabilitySummary)
	var i VulnerabilitySummaryRow
	err := row.Scan(&i.CriticalHighDevices, &i.UnknownSeverityDevices, &i.AffectedDevices)
	return i, err
}
